mapper.sql:
where 1=1

		and cact_llave = #{llaveTabla}


		and cact_estado = #{estado}


		and cact_responsable = #{responsable}


		and cact_documento = #{documento}


		and dact_fechaarrancar >= #{fechaArrancarMin}


		and dact_fechaarrancar  <   #{fechaArrancarMax}


		and dact_fecharegistro >= #{fechaRegistroMin}


		and dact_fecharegistro  <   #{fechaRegistroMax}


		and cact_usuarioregistro = #{usuarioRegistro}


		and dact_fechainactivo >= #{fechaInactivoMin}


		and dact_fechainactivo  <   #{fechaInactivoMax}


		and dact_fechaterminar >= #{fechaTerminarMin}


		and dact_fechaterminar  <   #{fechaTerminarMax}


		and dact_fechalimite >= #{fechaLimiteMin}


		and dact_fechalimite  <   #{fechaLimiteMax}


		and cact_usuarioinactivo = #{usuarioInactivo}


		and cact_actividadprevia = #{actividadPrevia}


		and cact_actividadsiguiente = #{actividadSiguiente}


		and dact_fechaleido >= #{fechaLeidoMin}


		and dact_fechaleido  <   #{fechaLeidoMax}
